rbac_router = APIRouter(prefix="/users/{user_id}/claims", tags=["rbac"])

@rbac_router.put("/custom-roles")
async def update_user_custom_roles(
    user_id: uuid.UUID,
    payload: RolesAssignmentPayload,
    user_manager: BaseUserManager = Depends(get_user_manager),
    current_user: User = Depends(current_active_user)
):
    if not current_user.is_superuser:
        raise HTTPException(status_code=403, detail="Forbidden: superuser authorization required to modify user roles")

    target_user = await user_manager.get(user_id)
    if not target_user:
        raise HTTPException(status_code=404, detail="User not found")

    updated_user = await user_manager.update(
        target_user,
        {"custom_roles": payload.roles, "is_verified": payload.is_verified},
        safe=False
    )
    return {"user_id": str(updated_user.id), "assigned_roles": updated_user.custom_roles}
